route=function(id,detail=false,i=0,push=true){if(id==='H01')detail=false;if(S.dirty&&!confirm('当前内容尚未保存。离开并保留草稿？'))return false;let old={id:S.page,detail:S.detail,row:S.row,scroll:window.scrollY};if(S.detail)S.detailScroll[key()]=window.scrollY;else filter().scroll=window.scrollY;if(push)S.history.push(old);S.showDiff=false;S.dirty=false;if(S.page!==id)S.editGeneric=null;S.page=id;S.detail=detail;S.row=i;S.previewProjectId=record().project;S.previewProject=projectName(S.previewProjectId);let p=page();currentNavigation();document.body.classList.remove('drawer');history[push?'pushState':'replaceState'](null,'','#'+id+(detail?'/'+p.detail+'/'+encodeURIComponent(objectId()):''));render();revealNavigation();window.scrollTo(0,detail?(S.detailScroll[key()]||0):(filter().scroll||0));return true};
tree=function(){let box=$('#sidebar'),top=box.scrollTop;baseTree();let nav=$('#tree');nav.querySelectorAll('[data-go]').forEach(b=>{if(!scope().pages.includes(b.dataset.go))b.remove()});box.scrollTop=top};
function searchTokens(p=page()){return p.search.split(/[/、，；（(]/).map(x=>x.replace(/[）)]/g,'').trim()).filter(Boolean)}
function searchValue(token,p,i){if(/自营类型/.test(token))return record(p,i).project==='DEMO-P02'?'内部':'客户';if(/审核状态|合同状态|可预览状态|授权状态/.test(token))return status(p,i);if(/任务类型|类型|类别/.test(token))return value(p.fields.find(f=>/类型|类别/.test(f))||'类型',p,i);if(/币种/.test(token))return value('币种',p,i);if(/期间|周期|账期/.test(token))return value('期间',p,i);if(token==='人员')return value('操作者',p,i);if(token==='对象')return value(p.fields.find(x=>/对象|事项|项目|服务/.test(x))||p.fields[0],p,i);if(/角色|主体/.test(token))return value('负责人/角色编号',p,i);if(/状态|阶段|结果|结论/.test(token))return status(p,i);if(/项目/.test(token))return value('所属项目',p,i);let fields=p.fields.filter(f=>f.includes(token)||token.includes(f));return fields.length?fields.map(f=>value(f,p,i)).join(' '):/名称|标题|编号|关键词|管理员/.test(token)?title(p,i)+' '+objectId(p,i):value(token,p,i)}
function matching(p=page()){let f=filter();return indices(p).filter(i=>(S.role==='Owner'||scope().projects.includes(record(p,i).project))&&(!record(p,i).isNew)&&(!f.q||([title(p,i),objectId(p,i),...p.fields.map(x=>value(x,p,i))].join(' ').toLowerCase().includes(f.q.toLowerCase())))&&Object.entries(f.facets||{}).every(([t,v])=>!v||(p.id==='T02'&&t==='状态'&&v==='执行与受阻'?['已接未执行','进行中','受阻','暂停'].includes(status(p,i)):searchValue(t,p,i)===v)))}
filters=function(){let p=page(),f=filter();return '<form class="filters" id="searchform"><input name="q" aria-label="'+esc(p.search)+'" placeholder="搜索'+esc(p.search)+'" value="'+esc(f.q)+'">'+searchTokens(p).filter(t=>!/名称|标题|编号|关键词|管理员/.test(t)).map(t=>{let vals=[...new Set(indices(p).filter(i=>S.role==='Owner'||scope().projects.includes(record(p,i).project)).map(i=>searchValue(t,p,i)))];if(/状态|阶段/.test(t)&&p.id==='T02')vals=[...new Set([...vals,'未发送','已发送待接','已接未执行','进行中','受阻','失败','暂停','执行与受阻','结果待验','已验收','未知'])];return '<select name="facet:'+esc(t)+'" aria-label="'+esc(t)+'"><option value="">全部'+esc(t)+'</option>'+vals.map(v=>'<option '+((f.facets||{})[t]===v?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select>'}).join('')+btn('搜索','type="submit"',true)+btn('重置','type="button" data-action="reset"')+'</form>'};
function listFields(p=page()){let priority={S02:['模型','用途','连接状态','负责人','费用来源','最近检测','密钥配置状态','启停状态'],S01:['角色','项目范围','功能范围','操作范围','状态','通知偏好'],T02:['所属项目','负责人/角色编号','状态','进度','最后有效回执','下一步/阻塞'],P01:['客户/内部','负责人及AI角色','阶段','下一节点','更新时间','预览/交付状态'],P02:['负责人及AI角色','阶段','下一节点','更新时间','预览/交付状态']};return [...new Set(priority[p.id]||p.fields.filter((x,i)=>i>0))]}
list=function(){let p=page(),f=filter(),edit=['S01','S02','W01','W02','W05','S03'].includes(p.id);let h=heading(p.name,p.id==='S02'?'连接状态、负责人、费用来源分别核对。':'查看当前事项，明确下一步。',p.id==='S02'&&allowedAction('edit')?btn('添加连接','data-action="add"',true):'');if(p.template==='metrics')h+='<div class="summary-grid">'+(p.id==='F04'?['收入确认','已核实际成本','暂估成本']:['实际值','目标值','指标口径']).map(t=>'<section class="card"><p>'+esc(t)+'</p><strong>待核实</strong><small>期间、币种及单位待核实</small></section>').join('')+'</div>';if(p.id==='T01')h+='<div class="summary-grid">'+['待接件','执行与受阻','结果待验'].map(t=>'<section class="card"><h2>'+t+'</h2>'+btn('查看任务','data-taskfilter="'+t+'"')+'</section>').join('')+'</div>';h+='<section class="card">'+filters();let all=matching(),total=all.length;f.n=Math.min(f.n,Math.max(1,Math.ceil(total/20)));let shown=all.slice((f.n-1)*20,f.n*20),fields=listFields(p);if(!total)return h+'<div class="empty"><h2>没有符合条件的记录</h2>'+btn('清空筛选','data-action="reset"')+'</div></section>';h+='<div class="table-scroll"><table class="table"><thead><tr><th>'+esc(p.fields[0])+'</th>'+fields.map(x=>'<th>'+esc(x)+'</th>').join('')+'<th>操作</th></tr></thead><tbody>'+shown.map(i=>'<tr><td>'+esc(title(p,i))+'<small>'+badge(status(p,i))+'</small></td>'+fields.map(x=>'<td>'+esc(value(x,p,i))+'</td>').join('')+'<td>'+btn(edit?'编辑':'查看详情','data-row="'+i+'"')+'</td></tr>').join('')+'</tbody></table></div><div class="mobile-list">'+shown.map(i=>'<article class="record"><div><strong>'+esc(title(p,i))+'</strong>'+badge(status(p,i))+'</div><dl>'+fields.map(x=>'<dt>'+esc(x)+'</dt><dd>'+esc(value(x,p,i))+'</dd>').join('')+'</dl>'+btn(edit?'编辑':'查看详情','data-row="'+i+'"')+'</article>').join('')+'</div><div class="pagination">'+btn('上一页','data-page="-1" '+(f.n===1?'disabled':''))+'<span>第 '+f.n+' / '+Math.ceil(total/20)+' 页 · '+total+' 条</span>'+btn('下一页','data-page="1" '+(f.n*20>=total?'disabled':''))+'</div></section>';return h};
function diffRows(before,after){return [...new Set([...Object.keys(before),...Object.keys(after)])].filter(f=>!f.startsWith('_')&&before[f]!==after[f]).map(f=>'<tr><th>'+esc(f)+'</th><td>'+esc(before[f]??'待核实')+'</td><td>'+esc(after[f]??'待核实')+'</td></tr>').join('')}
function diffHTML(){let before=COPY(S.saved[key()]||record().fields),after=currentDraft();if(page().detail==='WE'){let m=(before._modules||record().originalModules)?.find(x=>x.name===S.module);if(m)before={...before,...m.fields};}return '<h3>保存前 / 当前草稿</h3><table class="diff"><tr><th>字段</th><th>保存前</th><th>当前草稿</th></tr>'+editFields().filter(f=>!/密钥|连接状态/.test(f)).map(f=>'<tr><th>'+esc(f)+'</th><td>'+esc(before[f]??value(f))+'</td><td>'+esc(editValue(f))+'</td></tr>').join('')+'</table>'}
function previewWE(){let fields=moduleFields();return '<h2>'+esc(fields['模块标题'])+'</h2><p>'+esc(fields['正文文案'])+'</p><p>'+esc(fields['素材'])+'</p>'+btn(esc(fields['按钮文字']),'data-action="linkpreview"')+'<p>'+esc(fields['按钮链接'])+'</p><small>模块顺序：'+moduleSet().map(x=>esc(x.name)).join(' → ')+'</small>'}
editor=function(){let p=page(),d=p.detail,fields=[...new Set([...editFields(),...(S.editGeneric===p.id?(specs[p.id]?.fields||family[p.detail]?.fields||[]):[])])];let h=heading(d==='MD'?'模型连接配置':d==='AD'?'管理员范围编辑':d==='WE'?'编辑官网页面':p.name,'修改后核对差异，保存与取消分别处理。',btn('← 返回来源','data-action="back"'));h+='<div class="notice">'+(d==='AD'?'角色与操作范围待确认。':d==='MD'?'费用来源待核实；密钥仅显示配置状态。':'当前版本：待确认 · 草稿')+'</div>';if(d==='WE')h+='<div class="workspace"><section class="card module-list"><h2>页面模块</h2>'+moduleSet().map(x=>btn((x.name===S.module?'✓ ':'')+esc(x.name),'data-module="'+esc(x.name)+'"')).join('')+btn('↑ 上移','data-action="上移"')+btn('↓ 下移','data-action="下移"')+'</section>';h+='<section class="card"><h2>基本内容</h2><form id="editform"><div class="fields">'+fields.map((f,i)=>'<div class="field '+(/文案|范围/.test(f)?'full':'')+'"><label for="f'+i+'">'+esc(f)+'</label>'+(/密钥|连接状态/.test(f)?'<p>'+esc(value(f))+'</p>':/文案|范围/.test(f)?'<textarea id="f'+i+'" name="'+esc(f)+'">'+esc(editValue(f))+'</textarea>':'<input id="f'+i+'" name="'+esc(f)+'" value="'+esc(editValue(f))+'" '+(i===0?'required':'')+'>')+'</div>').join('')+'</div><p class="validation" id="validation"></p><div class="actions">'+(allowedAction('edit')?btn('保存草稿','type="submit"',true):'')+btn('取消','type="button" data-action="cancel"')+(d==='MD'&&allowedAction('edit')?btn('测试连接','type="button" data-action="test"')+btn('启用 / 停用','type="button" data-action="enable"'):btn('预览差异','type="button" data-action="preview"'))+(d==='WN'?btn('↑ 上移','type="button" data-action="上移"')+btn('↓ 下移','type="button" data-action="下移"'):'')+'</div></form><div id="localresult">'+(S.showDiff?diffHTML():'')+'</div>'+eventHTML()+'</section>';if(d==='WE')h+='<section class="card"><h2>同版预览</h2><div class="preview" id="wepreview">'+previewWE()+'</div>'+goButton('发布记录','W06',true)+btn('发布内容','data-action="publish"')+'</section></div>';else h+=relations(d==='MD'?['S02','F03']:d==='AD'?['S01','S04']:['W06','W02']);return h};
function publicationDiff(){let web=revisionDiff('W02','官网内容'),nav=revisionDiff('W01','官网导航');return web+nav}
function revisionDiff(id,label){let p=P.find(p=>p.id===id),r=record(p,relatedRow(id)),versions=r.revisions||[];if(versions.length<2)return '<p>当前对象暂无两份保存版本可比较。</p>';let a=versions[versions.length-2],b=versions[versions.length-1];let flatten=f=>{let out={};for(let [k,v] of Object.entries(f)){if(k==='_modules'){out['模块顺序']=v.map(m=>m.name).join(' → ');for(let m of v)for(let [field,value] of Object.entries(m.fields))out[m.name+' · '+field]=value;}else if(!k.startsWith('_'))out[k]=v}return out};return '<h3>'+esc(label)+' v'+a.version+' / v'+b.version+'</h3><table class="diff"><tr><th>字段</th><th>之前</th><th>之后</th></tr>'+diffRows(flatten(a.fields),flatten(b.fields))+'</table>'}
function noteForm(){return '<form id="objectnoteform"><label for="objectnote">当前对象意见 / 跟进</label><textarea id="objectnote" name="note">'+esc(S.drafts[key()+':note']||'')+'</textarea>'+btn('保存记录','type="submit"',true)+'</form>'}
function eventHTML(){return '<details open><summary>操作记录</summary>'+record().events.map(e=>'<p>#'+e.sequence+' '+esc(e.action)+' → '+esc(e.result)+'</p>').join('')+'</details>'}
function act(a){if(!demo()||!allowedAction(a==='test'||a==='enable'?'edit':'act')||(!['normal','error'].includes(S.state))||(S.state==='error'&&a!=='test'))return false;let r=record(),map={'发送指令':'已发送待接','接件':'已接未执行','开始执行':'进行中','提交结果':'结果待验','验收':'已验收','通过验收':'已验收','退回意见':'待复验','暂停':'暂停','恢复':'进行中','释放实例':'已释放','test':S.state==='error'?'异常':'可用','enable':r.status==='停用'?'待检测':'停用','确认范围':'已确认','交付':'已交付','跟进':'跟进中','上下架':'展示待确认','处置':'处理中','验证恢复证据':'待核实恢复','发布内容':'待发布','publish':'待发布','提交测试记录':'待复验','提交产品化结果':'待验证','记录复验意见':'待复验','记录客户意见':'变更待确认','更正申请':'待核实','页面确认':'页面待复验'};if(page().id==='T02'&&status()==='已验收'&&['发送指令','接件','开始执行','提交结果','验收','暂停','恢复'].includes(a)){local('当前任务已验收，不重复执行或重置阶段；未改变任务。');return false}if(page().id==='T02'&&((a==='暂停'&&status()==='暂停')||(a==='恢复'&&!['暂停','受阻'].includes(status())))){local('当前阶段为'+status()+'，不能重复暂停或从此阶段恢复；未改变任务。');return false}let required={'发送指令':'未发送','接件':'已发送待接','开始执行':'已接未执行','提交结果':'进行中','验收':'结果待验'};if(required[a]&&status()!==required[a]){local(status()===map[a]?'当前任务已处于'+status()+'，不重复执行。':'当前阶段为'+status()+'，此操作需要：'+required[a]+'；未改变任务。');return false}if(a==='恢复'&&r.project==='DEMO-P02'){local('项目暂停，保留待负责人决定；未自动恢复。');return false}if(a==='enable'){r.enabled=r.enabled===false;map[a]=r.enabled?(r.lastTest||'待检测'):'停用'}if(map[a])r.status=map[a];if(a==='test')r.lastTest=map[a];if(a==='test')r.tested=(r.tested||0)+1;r.next=r.status==='已验收'?'核对交付事项':r.status==='结果待验'?'等待有效主体验收':'核对下一阶段及有效回执';if(a==='test'&&r.enabled===false)r.status='停用';r.events.push({sequence:r.events.length+1,action:({test:'测试连接',enable:'启停连接',publish:'发布内容'})[a]||a,result:map[a]||'已记录，处理结果待确认'});if(page().id==='T02'){r.next=taskNext(r.status);let attempt=record(P.find(p=>p.id==='T03'),S.row);attempt.status=r.status;attempt.events=COPY(r.events);attempt.next=r.next;}persist();render();local('操作记录已保存，处理结果待确认。');return true}
confirmAction=function(a){if(!demo()||!allowedAction(a==='enable'?'edit':'act')){feedback('当前范围不可操作，请核对权限。');return}$('#dialogtitle').textContent=a==='enable'?'更改连接启停状态':a;$('#dialogtext').textContent='请核对当前对象与操作范围。';$('#confirm').showModal();$('#confirm').onclose=()=>{if($('#confirm').returnValue==='confirm')act(a)}};
