detail=function(){let p=page();if(['WE','WN','MD','AD','PR'].includes(p.detail)||S.editGeneric===p.id||['W05','S03'].includes(p.id))return p.detail==='PR'?preview():editor();let sp=specs[p.id]||family[p.detail],oldRel=rel.GD;rel.GD=sp?.rel||[];let h=baseDetail();rel.GD=oldRel;if(sp){h+=fieldCard(p.name+' · 专属信息',sp.fields)+relations(sp.rel)+'<section class="card"><h2>当前对象操作</h2><div class="actions">'+sp.actions.filter(a=>allowedAction(/编辑|修改/.test(a)?'edit':'act')).map(a=>btn(a,'data-action="'+esc(a)+'"')).join('')+'</div></section>'}if(p.detail==='TD'){h+='<section class="card"><h2>关联页面意见</h2>'+Object.entries(S.opinions||{}).filter(([k])=>k.startsWith('opinion:'+record().project+':')).map(([k,t])=>'<p>'+esc(k.split(':').slice(2).join(' · '))+'：'+esc(t)+'</p>').join('')+'</section>';}if(p.detail==='TD')h+='<section class="card"><div class="actions">'+['开始执行','暂停','恢复'].filter(()=>allowedAction('act')).map(a=>btn(a,'data-action="'+a+'"')).join('')+'</div></section>';h+='<section class="card">'+(S.noteOpen===key()?noteForm():'')+(record().notes||[]).map(t=>'<p>'+esc(t)+'</p>').join('')+eventHTML()+'</section>';return h};
