preview=function(){let v=versionData(S.version);return heading(v['标题']+' · 预览与意见','页面确认、复验与整体验收分别记录。',btn('← 返回来源','data-action="back"'))+'<div class="filters"><select id="previewproject" aria-label="选择项目">'+scope().projects.filter(id=>indices(P.find(p=>p.id==='P01')).some(i=>record(P.find(p=>p.id==='P01'),i).project===id)).map(id=>'<option value="'+id+'" '+(S.previewProjectId===id?'selected':'')+'>'+projectName(id)+'</option>').join('')+'</select><select id="previewversion" aria-label="选择版本">'+['v2','v1'].map(v=>'<option '+(S.version===v?'selected':'')+'>'+v+'</option>').join('')+'</select>'+btn('对比版本','data-action="compare"')+'</div><div class="workspace"><section class="card module-list"><h2>页面</h2>'+['首页','服务列表','交付结果'].map(t=>btn((S.previewPage===t?'✓ ':'')+t,'data-previewpage="'+t+'"')).join('')+'</section><section class="card"><h2>'+esc(S.previewPage)+' · '+S.version+'</h2><div class="preview"><h2>'+esc(v['标题'])+'</h2><p>'+esc(v['操作入口'])+'</p><p>'+esc(v['交付摘要'])+'</p></div><div class="actions">'+btn('打开授权预览','data-action="openpreview"')+(allowedAction('act')?btn('记录页面确认','data-action="页面确认"'):'')+'</div><div id="localresult"></div></section><section class="card"><h2>意见与复验</h2><form id="opinionform"><label for="opinion">当前页面意见</label><textarea id="opinion" '+(allowedAction('act')?'required':'readonly aria-readonly="true"')+'>'+esc(S.drafts[opinionKey()]??S.opinions?.[opinionKey()]??'')+'</textarea>'+(allowedAction('act')?btn('记录意见','type="submit"',true):'<p>当前范围只读，不能提交意见。</p>')+'</form><p>'+esc(projectName(S.previewProjectId)+' / '+S.previewPage+' / '+S.version)+'</p>'+relations(['T02','P12'])+'<details><summary>历史意见</summary>'+Object.entries(S.opinions||{}).filter(([k])=>k.startsWith('opinion:'+S.previewProjectId+':'+S.previewPage+':')).map(([k,t])=>'<p>'+esc(k.split(':').pop())+'：'+esc(t)+'</p>').join('')+'</details></section></div>'};
function switchPreview(kind,v){if(S.dirty&&!confirm('切换并保留当前项目、页面及版本的意见草稿？')){render();return false}S.dirty=false;if(kind==='project'){S.previewProjectId=v;S.previewProject=projectName(v);S.row=Math.max(0,parseInt(v.slice(6),10)-1);S.previewPage='首页';S.version='v2'}if(kind==='version')S.version=v;if(kind==='page')S.previewPage=v;render();return true}
render=function(){tree();let p=page(),deny=S.state==='denied'||!canView();$('#path').textContent=deny?'查看范围待确认':[p.domain,p.group,p.name,S.detail?'详情':null].filter(Boolean).join(' / ');let editable=S.detail&&(['WE','WN','MD','AD'].includes(p.detail)||S.editGeneric===p.id);let blocked=deny||(S.state!=='normal'&&!(editable&&['error','conflict'].includes(S.state)))||(!demo()&&!(S.page==='H01'&&!S.detail&&S.role==='Owner'&&S.state==='normal'));if(blocked){let keep=S.state;S.state=deny?'denied':S.state==='normal'?'unconnected':S.state;$('#content').innerHTML=heading(deny?'查看范围待确认':p.name,'',goButton('返回首页','H01'))+'<section class="card">'+stateBlock()+'</section>';S.state=keep;}else{$('#content').innerHTML=S.page==='H01'&&!S.detail?(S.role==='Owner'?home():heading('工作台总览','查看范围待确认。')+'<section class="card"><h2>当前项目</h2><p>示例服务门户</p>'+relations(scope().pages.filter(id=>['P01','T02','W02','S02'].includes(id)))+'</section>'):S.detail?detail():list();if(editable&&S.state!=='normal')$('#content').innerHTML='<div class="notice warning">'+(S.state==='conflict'?'内容已更新，请核对后再保存。':'读取失败，保留当前草稿；未保存。')+'</div>'+$('#content').innerHTML;if(!allowedAction('act'))$('#content').querySelectorAll('[data-action]').forEach(b=>{let a=b.dataset.action;if(!['back','cancel','reset','retry','preview','compare','openpreview','linkpreview'].includes(a)&&!(['test','enable','add','上移','下移'].includes(a)&&allowedAction('edit')))b.remove()})}drawNotes()};
