function setTaskStage(v){if(!canSetTaskStage()){render();local('请在任务详情中调整阶段。');return false}let r=record(),before=status();if(before===v||before==='已验收'){render();local(before===v?'当前任务已处于'+v+'，不重复切换。':'已验收任务不能重置阶段。');return false}if(!['未发送','已发送待接','已接未执行','进行中','受阻','暂停','结果待验','已验收','同版待核对'].includes(v))return false;r.status=v;r.next=taskNext(v);r.events.push({sequence:r.events.length+1,action:'调整阶段',result:v});let attempt=record(P.find(p=>p.id==='T03'),S.row);attempt.status=v;attempt.next=r.next;attempt.events=COPY(r.events);persist();render();return true}
