value=function(f,p=page(),i=0){let r=record(p,i);if(!demo()||r.fields[f]!==undefined)return displayValue(f,p,i);if(p.id==='P02'&&/客户|内部/.test(f))return '内部';if(f===p.fields[0]||/^(渠道|活动|目标|问题|任务|模块|产品名|方案名称|证据名|发布对象|操作对象)$/.test(f))return title(p,i);if(/状态|阶段|结论/.test(f))return /付款|核销|履约|交付|续费|签发|归因/.test(f)?'待核实':status(p,i);if(/金额|费用|成本|收入|利润|应付|实收|佣金|比例|差额|调整|余额|贡献值|客户脱敏数|可看页面数|进度|实际值|目标值/.test(f))return '待确认';if(/币种/.test(f))return '人民币 CNY';if(/期|时间|更新|日期|回执|编号|版本|单位|证据|依据|授权|权利/.test(f))return '待确认';if(/项目/.test(f))return projectName(r.project);if(/负责人|责任人|审核人|操作者|处置人/.test(f))return ['示例项目负责人','示例业务负责人','示例资料负责人'][i%3];if(/摘要|概要|范围|职责|权益|用途|影响|事项/.test(f))return ({C02:'服务门户需求咨询，具体范围待确认',C03:'首页、服务列表与交付内容待确认',C04:'核对页面层级与服务信息',C05:'适用服务与交付内容待确认',C08:'服务范围与合同条款待确认',E06:'服务方案及复用许可待确认',S06:'服务影响范围待确认',S07:'服务情况及下一步待确认'})[p.id]||'具体内容待确认';return displayValue(f,p,i)};
