async function readTasks(){let generation=++taskRead.generation;taskRead.state='loading';taskRead.records=[];render();try{let records=await window.AdminTaskRead.load(window.fetch.bind(window));if(generation!==taskRead.generation||S.page!=='T02')return;taskRead.records=records;taskRead.state='ready';if(taskRead.pendingId!==null&&S.page==='T02'){let i=records.findIndex(r=>r.task_id===taskRead.pendingId);taskRead.pendingId=null;if(i>=0)originalRoute('T02',true,i,false);else {S.detail=false;S.row=0}}}catch(e){if(generation!==taskRead.generation||S.page!=='T02')return;taskRead.state=e.message==='ACCESS_DENIED'?'denied':'error'}render()}
